  "inlineSchema": "// GreenRouter — skema database gateway AI\n// Provider & pool key hulu, katalog model + routing per model,\n// key klien (tersimpan sebagai hash), dan log pemakaian.\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nmodel User {\n  id                 String   @id @default(cuid())\n  email              String   @unique\n  passwordHash       String\n  role               String   @default(\"ADMIN\")\n  name               String?\n  image              String?\n  authProviders      String   @default(\"password\")\n  isActive           Boolean  @default(true)\n  // Kuota token per siklus 7 hari (jangkar: tanggal akun dibuat).\n  // Nama kolom DB dipertahankan dari era limit bulanan lewat @map.\n  tokenLimit         Int?     @map(\"tokenLimitMonthly\")\n  // Batas request per jam (jendela bergeser 60 menit, dihitung per akun).\n  // NULL = tanpa batas, sama seperti tokenLimit.\n  requestLimitHourly Int?\n  apiKeys            ApiKey[]\n  createdAt          DateTime @default(now())\n  updatedAt          DateTime @updatedAt\n}\n\nmodel ApiKey {\n  id         String     @id @default(cuid())\n  userId     String?\n  user       User?      @relation(fields: [userId], references: [id], onDelete: SetNull)\n  name       String\n  prefix     String\n  keyHash    String     @unique\n  isActive   Boolean    @default(true)\n  lastUsedAt DateTime?\n  usageLogs  UsageLog[]\n  createdAt  DateTime   @default(now())\n  updatedAt  DateTime   @updatedAt\n\n  @@index([keyHash])\n}\n\nmodel Provider {\n  id                String        @id @default(cuid())\n  name              String        @unique\n  baseUrl           String\n  isActive          Boolean       @default(true)\n  // URL endpoint sisa kuota per key (mis. Dahl /tokens/current). Bila terisi,\n  // gateway mengecek sisa token key SEBELUM setiap request diteruskan;\n  // sisa 0 berarti key ditandai LIMITED dan dikeluarkan dari rotasi.\n  quotaCheckUrl     String?\n  // false bila hulu tidak melayani endpoint Anthropic /messages secara\n  // native (mis. Dahl); jalur Anthropic untuk provider ini diterjemahkan\n  // GreenRouter lewat endpoint OpenAI-nya (lihat anthropic-translate.ts).\n  supportsAnthropic Boolean       @default(true)\n  upstreamKeys      UpstreamKey[]\n  routes            ModelRoute[]\n  usageLogs         UsageLog[]\n  createdAt         DateTime      @default(now())\n  updatedAt         DateTime      @updatedAt\n}\n\nmodel UpstreamKey {\n  id            String     @id @default(cuid())\n  providerId    String\n  provider      Provider   @relation(fields: [providerId], references: [id], onDelete: Cascade)\n  label         String\n  encryptedKey  String\n  keyHint       String\n  status        String     @default(\"ACTIVE\") // ACTIVE | COOLDOWN | DISABLED | LIMITED (402, menunggu tindakan admin)\n  cooldownUntil DateTime?\n  failCount     Int        @default(0)\n  usageLogs     UsageLog[]\n  createdAt     DateTime   @default(now())\n  updatedAt     DateTime   @updatedAt\n\n  @@index([providerId, status])\n}\n\nmodel ModelCatalog {\n  id              String       @id @default(cuid())\n  modelId         String       @unique\n  displayName     String\n  // Metadata tampilan katalog (disinkron dari provider hulu, bisa diedit admin).\n  contextTokens   Int?\n  maxOutputTokens Int?\n  inputModalities String? // daftar dipisah koma: text,image,video,pdf,audio\n  capabilities    String? // daftar dipisah koma: reasoning,tool_call,structured_output,attachment\n  knowledgeCutoff String? // format \"YYYY-MM\"\n  routes          ModelRoute[]\n  createdAt       DateTime     @default(now())\n  updatedAt       DateTime     @updatedAt\n}\n\nmodel ModelRoute {\n  id              String       @id @default(cuid())\n  modelId         String\n  model           ModelCatalog @relation(fields: [modelId], references: [id], onDelete: Cascade)\n  providerId      String\n  provider        Provider     @relation(fields: [providerId], references: [id], onDelete: Cascade)\n  upstreamModelId String\n  priority        Int          @default(0)\n  isActive        Boolean      @default(true)\n  createdAt       DateTime     @default(now())\n  updatedAt       DateTime     @updatedAt\n\n  @@unique([modelId, providerId])\n  @@index([modelId, isActive])\n}\n\n// Pengumuman dari admin yang tampil di dashboard semua user.\nmodel Announcement {\n  id        String   @id @default(cuid())\n  title     String\n  body      String\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// Hasil tes kesehatan otomatis: satu chat sederhana ke tiap model katalog\n// sekali per 24 jam (dipicu watchdog). Sengaja BUKAN UsageLog: tes ini\n// bukan pemakaian user, tidak boleh mengotori statistik maupun kuota.\nmodel ModelHealthCheck {\n  id        String   @id @default(cuid())\n  modelId   String\n  status    String // \"SUCCESS\" | \"ERROR\"\n  latencyMs Int\n  error     String?\n  checkedAt DateTime @default(now())\n\n  @@index([modelId, checkedAt])\n}\n\nmodel UsageLog {\n  id               String       @id @default(cuid())\n  // Pemilik key saat request terjadi — ditulis permanen (denormal) agar\n  // hitungan kuota TIDAK reset saat user menghapus key-nya: relasi apiKey\n  // di bawah SetNull, kolom ini tidak ikut berubah. Tanpa relasi FK supaya\n  // riwayat tetap utuh walau user/key dihapus.\n  userId           String?\n  apiKeyId         String?\n  apiKey           ApiKey?      @relation(fields: [apiKeyId], references: [id], onDelete: SetNull)\n  providerId       String?\n  provider         Provider?    @relation(fields: [providerId], references: [id], onDelete: SetNull)\n  upstreamKeyId    String?\n  upstreamKey      UpstreamKey? @relation(fields: [upstreamKeyId], references: [id], onDelete: SetNull)\n  modelId          String\n  promptTokens     Int?\n  completionTokens Int?\n  totalTokens      Int?\n  latencyMs        Int?\n  status           String // SUCCESS | ERROR\n  error            String?\n  createdAt        DateTime     @default(now())\n\n  @@index([createdAt])\n  @@index([apiKeyId, createdAt])\n  @@index([userId, createdAt])\n}\n",
